mapper.select:
 select
 assets .*,co.id as companyId, co.name as companyName, concat(ifnull(co.name, ''), case when ifnull(co.name, '') = '' then '' else '-' end, department.name) as departmentName, concat(staff.name, case when staff.status = '离职' then '（离职）' else '' end) as staffName
 from assets 
 left join department on assets .department_id=department.id
 left join company co on department.company_id = co.id
 left join staff on assets .staff_id=staff.id

     and assets.name like concat('%', #{name}, '%')
     and assets.category like concat('%', #{category}, '%')
     and assets.no like concat('%', #{no}, '%')
     and assets.status = #{status}
     and co.id = #{companyId}
     and assets.department_id = #{departmentId}
     and assets.staff_id = #{staffId}
     and assets.location like concat('%', #{location}, '%')
     and assets.date >= #{dateStart}
     and assets.date <= #{dateEnd}

order by assets.id desc
